type EditorialNivelDeInsegurancaAlimentarProps = {
  className?: string;
  definicao?: string;
  nivel?: string;
};

function EditorialNivelDeInsegurancaAlimentar({ className, definicao = "Incerteza sobre o acesso e possível perda de qualidade.", nivel = "LEVE" }: EditorialNivelDeInsegurancaAlimentarProps) {
  return (
    <div className={className || "[word-break:break-word] content-stretch flex flex-col gap-[8px] items-start leading-[30px] relative text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[368px]"} data-node-id="51:146" data-name="Editorial / Nível de insegurança alimentar">
      <p className="font-['Archivo:Bold'] font-bold relative shrink-0 w-[368px]" data-node-id="51:147" style={{ fontVariationSettings: '"wdth" 100' }}>
        {nivel}
      </p>
      <p className="font-['Archivo:Regular'] font-normal relative shrink-0 w-[368px]" data-node-id="51:148" style={{ fontVariationSettings: '"wdth" 100' }}>
        {definicao}
      </p>
    </div>
  );
}

type EditorialPainelEbiaInterativoProps = {
  className?: string;
  estado?: "Recolhido" | "Expandido • LEVE" | "Expandido • MODERADA" | "Expandido • GRAVE";
};

export default function EditorialPainelEbiaInterativo({ className, estado = "Recolhido" }: EditorialPainelEbiaInterativoProps) {
  const isExpandidoGrave = estado === "Expandido • GRAVE";
  const isExpandidoLeve = estado === "Expandido • LEVE";
  const isExpandidoModerada = estado === "Expandido • MODERADA";
  const isExpandidoModeradaOrExpandidoGrave = ["Expandido • MODERADA", "Expandido • GRAVE"].includes(estado);
  const isRecolhido = estado === "Recolhido";
  const isRecolhidoOrExpandidoModeradaOrExpandidoGrave = ["Recolhido", "Expandido • MODERADA", "Expandido • GRAVE"].includes(estado);
  return (
    <div className={className || "bg-[var(----cor-terracota,#ad6c49)] h-[556px] overflow-clip relative w-[416px]"} id={isExpandidoGrave ? "node-616_584" : isExpandidoModerada ? "node-616_569" : isExpandidoLeve ? "node-616_554" : "node-616_553"}>
      <p className="[word-break:break-word] absolute font-['Libre_Baskerville:Regular'] font-normal h-[30px] leading-[normal] left-[24px] text-[24px] text-[color:var(--margem-cor-papel,#f2efdf)] top-[26px] w-[368px]" id={isExpandidoGrave ? "node-616_585" : isExpandidoModerada ? "node-616_570" : isExpandidoLeve ? "node-616_555" : "node-616_540"}>
        NÍVEIS DA EBIA:
      </p>
      {isRecolhidoOrExpandidoModeradaOrExpandidoGrave && (
        <>
          <div className={`absolute bg-[#985a38] left-[14px] rounded-[12px] w-[391px] ${isExpandidoModeradaOrExpandidoGrave ? "h-[86px] top-[92px]" : "h-[124px] top-[109px]"}`} id={isExpandidoGrave ? "node-616_586" : isExpandidoModerada ? "node-616_571" : "node-616_541"} data-name="Fundo • LEVE" />
          <EditorialNivelDeInsegurancaAlimentar className={`[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[368px] ${isExpandidoModeradaOrExpandidoGrave ? "top-[102px]" : "cursor-pointer text-left top-[120px]"}`} definicao={isExpandidoModeradaOrExpandidoGrave ? "Incerteza e perda de qualidade." : undefined} />
        </>
      )}
      {["Recolhido", "Expandido • LEVE", "Expandido • GRAVE"].includes(estado) && <div className={`absolute bg-[#985a38] left-[14px] rounded-[12px] w-[391px] ${isExpandidoGrave ? "h-[86px] top-[190px]" : isExpandidoLeve ? "h-[86px] top-[312px]" : "h-[124px] top-[246px]"}`} id={isExpandidoGrave ? "node-616_588" : isExpandidoLeve ? "node-616_558" : "node-616_545"} data-name="Fundo • MODERADA" />}
      {["Recolhido", "Expandido • GRAVE"].includes(estado) && <EditorialNivelDeInsegurancaAlimentar className={`[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[368px] ${isExpandidoGrave ? "top-[200px]" : "cursor-pointer text-left top-[256px]"}`} definicao={isExpandidoGrave ? "Menos alimentos entre adultos." : "Redução da quantidade de comida entre adultos."} nivel="MODERADA" />}
      {["Recolhido", "Expandido • MODERADA"].includes(estado) && <div className={`absolute bg-[#985a38] left-[14px] rounded-[12px] w-[391px] ${isExpandidoModerada ? "h-[86px] top-[392px]" : "h-[124px] top-[382px]"}`} id={isExpandidoModerada ? "node-616_575" : "node-616_549"} data-name="Fundo • GRAVE" />}
      {isRecolhido && (
        <>
          <EditorialNivelDeInsegurancaAlimentar className="[word-break:break-word] absolute content-stretch cursor-pointer flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] text-left top-[392px] w-[368px]" definicao="Privação alimentar intensa, com experiência de fome." nivel="GRAVE" />
          <button className="absolute block cursor-pointer h-[124px] left-[14px] top-[109px] w-[391px]" data-node-id="618:574" data-name="Área de clique • LEVE" />
          <button className="absolute block cursor-pointer h-[124px] left-[14px] top-[246px] w-[391px]" data-node-id="618:576" data-name="Área de clique • MODERADA" />
          <button className="absolute block cursor-pointer h-[124px] left-[14px] top-[382px] w-[391px]" data-node-id="618:578" data-name="Área de clique • GRAVE" />
          <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal h-[18px] leading-[normal] left-[24px] text-[14px] text-[rgba(242,239,223,0.88)] top-[62px] w-[368px]" data-node-id="625:581" style={{ fontVariationSettings: '"wdth" 100' }}>
            Clique no card
          </p>
        </>
      )}
      {isExpandidoLeve && (
        <>
          <EditorialNivelDeInsegurancaAlimentar className="[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] top-[322px] w-[368px]" definicao="Menos alimentos entre adultos." nivel="MODERADA" />
          <div className="absolute bg-[#985a38] h-[86px] left-[14px] rounded-[12px] top-[410px] w-[391px]" data-node-id="616:560" data-name="Fundo • GRAVE" />
        </>
      )}
      {["Expandido • LEVE", "Expandido • MODERADA"].includes(estado) && <EditorialNivelDeInsegurancaAlimentar className={`[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[368px] ${isExpandidoModerada ? "top-[402px]" : "top-[420px]"}`} definicao="A fome pode alcançar crianças." nivel="GRAVE" />}
      {isExpandidoLeve && (
        <>
          <button className="absolute bg-[rgba(255,255,255,0)] block cursor-pointer h-[556px] left-0 top-0 w-[416px]" data-node-id="616:568" data-name="Fechar ao clicar fora • LEVE" />
          <div className="absolute bg-[#985a38] h-[208px] left-[14px] rounded-[12px] top-[92px] w-[391px]" data-node-id="616:556" data-name="Fundo • LEVE" />
          <EditorialNivelDeInsegurancaAlimentar className="[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] top-[102px] w-[368px]" definicao="Há preocupação ou incerteza quanto ao acesso aos alimentos no futuro. A qualidade da alimentação pode ser comprometida por estratégias para preservar a quantidade de comida." />
          <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal h-[18px] leading-[normal] left-[24px] text-[14px] text-[rgba(242,239,223,0.88)] top-[62px] w-[368px]" data-node-id="625:582" style={{ fontVariationSettings: '"wdth" 100' }}>
            Clique no card
          </p>
        </>
      )}
      {isExpandidoModerada && (
        <>
          <button className="absolute bg-[rgba(255,255,255,0)] block cursor-pointer h-[556px] left-0 top-0 w-[416px]" data-node-id="616:583" data-name="Fechar ao clicar fora • MODERADA" />
          <div className="absolute bg-[#985a38] h-[190px] left-[14px] rounded-[12px] top-[190px] w-[391px]" data-node-id="616:573" data-name="Fundo • MODERADA" />
          <EditorialNivelDeInsegurancaAlimentar className="[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] top-[200px] w-[368px]" definicao="Há redução da quantidade de alimentos entre os adultos e/ou ruptura nos padrões habituais de alimentação por falta de comida entre os adultos." nivel="MODERADA" />
          <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal h-[18px] leading-[normal] left-[24px] text-[14px] text-[rgba(242,239,223,0.88)] top-[62px] w-[368px]" data-node-id="625:583" style={{ fontVariationSettings: '"wdth" 100' }}>
            Clique no card
          </p>
        </>
      )}
      {isExpandidoGrave && (
        <>
          <button className="absolute bg-[rgba(255,255,255,0)] block cursor-pointer h-[556px] left-0 top-0 w-[416px]" data-node-id="616:598" data-name="Fechar ao clicar fora • GRAVE" />
          <div className="absolute bg-[#985a38] h-[208px] left-[14px] rounded-[12px] top-[288px] w-[391px]" data-node-id="616:590" data-name="Fundo • GRAVE" />
          <EditorialNivelDeInsegurancaAlimentar className="[word-break:break-word] absolute content-stretch flex flex-col gap-[8px] items-start leading-[30px] left-[24px] text-[20px] text-[color:var(--margem-cor-papel,#f2efdf)] top-[298px] w-[368px]" definicao="A redução da quantidade de alimentos também alcança as crianças, com ruptura nos padrões de alimentação de todos os moradores. Nessa situação, a fome passa a ser vivida no domicílio." nivel="GRAVE" />
          <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal h-[18px] leading-[normal] left-[24px] text-[14px] text-[rgba(242,239,223,0.88)] top-[62px] w-[368px]" data-node-id="625:584" style={{ fontVariationSettings: '"wdth" 100' }}>
            Clique no card
          </p>
        </>
      )}
    </div>
  );
}
